function findReportText(obj) {
  if (typeof obj === 'string') {
    const t = obj.trim();
    if (t.startsWith('{') && t.includes('oportunidades')) return t;
    return null;
  }
  if (Array.isArray(obj)) {
    for (const item of obj) {
      const found = findReportText(item);
      if (found) return found;
    }
    return null;
  }
  if (obj && typeof obj === 'object') {
    for (const key of Object.keys(obj)) {
      const found = findReportText(obj[key]);
      if (found) return found;
    }
  }
  return null;
}

const raw = $input.first().json;
const rawContent = findReportText(raw);

if (!rawContent) {
  throw new Error('Não encontrei o texto gerado. Estrutura recebida: ' + JSON.stringify(raw));
}

const cleaned = rawContent.replace(/```json/gi, '').replace(/```/g, '').trim();
const reportJson = JSON.parse(cleaned);
const input = $('When called by another workflow').first().json.query;
const id = 'rel_' + Date.now() + '_' + Math.random().toString(36).slice(2, 8);

const oportunidadesHtml = reportJson.oportunidades.map((o, i) => `
  <div class="op">
    <h3>${i + 1}. ${o.titulo}</h3>
    <p>${String(o.descricao).split(/\n\s*\n/).join('</p><p>')}</p>
  </div>
`).join('');

const html = `
<!DOCTYPE html>
<html lang="pt-BR">
<head>
<meta charset="UTF-8">
<style>
  body { font-family: Arial, Helvetica, sans-serif; color: #1c1f26; padding: 40px; }
  h1 { color: #2b3a67; font-size: 24px; margin-bottom: 4px; }
  .subtitle { color: #6b7280; margin-bottom: 24px; font-size: 13px; }
  .intro, .conclusao { font-size: 14px; line-height: 1.6; margin-bottom: 24px; }
  .op { margin-bottom: 18px; padding: 14px 16px; border-left: 4px solid #6c8cff; background: #f5f7ff; border-radius: 6px; }
  .op h3 { margin: 0 0 6px; font-size: 15px; color: #2b3a67; }
  .op p { margin: 0; font-size: 13px; line-height: 1.5; }
  .footer { margin-top: 32px; font-size: 11px; color: #9aa0ad; }
</style>
</head>
<body>
  <h1>Diagnóstico de Oportunidades de Automação</h1>
  <div class="subtitle">${input.empresa} — ${input.segmento} — ${input.cidade_estado}</div>
  <div class="intro"><p>${reportJson.introducao}</p></div>
  <h2>Oportunidades de Automação</h2>
  ${oportunidadesHtml}
  <div class="conclusao"><p>${reportJson.conclusao}</p></div>
  <div class="footer">Relatório gerado automaticamente pela YARA — Agente de IA de Diagnóstico de Automações.</div>
</body>
</html>`;

return [{ json: { id, html, nome: input.nome, empresa: input.empresa, segmento: input.segmento, email: input.email } }];

